                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title=\"Q3 hard-data vs July IMF path\"
            subtitle=\"Context meters ??? soft landing still split across trade/growth/prices\"
          >
            <div className=\"h-80 w-full min-w-0\">
              <ResponsiveContainer width=\"100%\" height=\"100%\">
                <BarChart
                  data={hardDumbbells}
