                  <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#e2e8f0\" />
                  <XAxis type=\"number\" tick={{ fontSize: 11 }} />
                  <YAxis type=\"category\" dataKey=\"label\" width={120} tick={{ fontSize: 10 }} />
                  <Tooltip
                    formatter={(v: number, name: string) => [
                      \\\`\\\${Number(v).toFixed(1)}%\\\`,
