                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title=\"PPP GDP stock ladder\"
            subtitle=\"Carried ~2025 weights ??? China ?? US ?? India = 42% Top-3\"
          >
            <div className=\"h-96 w-full min-w-0\">
              <ResponsiveContainer width=\"100%\" height=\"100%\">
                <BarChart
                  data={pppBars}
