              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === \"trade\" && (
        <div className=\"grid gap-6 lg:grid-cols-2\">
          <ChartCard
            title=\"Merchandise trade-growth contribution\"
            subtitle=\"WTO 2025 regional decomposition ??? Asia 71% / 3.2 pp\"
          >
            <div className=\"h-80 w-full min-w-0\">
              <ResponsiveContainer width=\"100%\" height=\"100%\">
                <PieChart>
                  <Pie
                    data={tradePie}
                    dataKey=\"value\"
                    nameKey=\"name\"
                    cx=\"50%\"
                    cy=\"50%\"
                    innerRadius={55}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {tradePie.map((s) => (
                      <Cell key={s.name} fill={s.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v: number) => [fmtPct(v, 0), \"Share of vol. growth\"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title=\"CPB merchandise volume rebound\"
            subtitle=\"Mar???May MoM path ??? flow overlay, not a re-rank of 2025 shares\"
          >
            <div className=\"h-80 w-full min-w-0\">
              <ResponsiveContainer width=\"100%\" height=\"100%\">
                <LineChart data={CPB_PATH} margin={{ top: 12, right: 16, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#e2e8f0\" />
                  <XAxis dataKey=\"month\" tick={{ fontSize: 11 }} />
