                    </p>
                    <p className=\"text-xs text-slate-500\">
                      {s.confidence} ??? {s.note}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      {view === \"prices\" && (
        <div className=\"grid gap-6 lg:grid-cols-2\">
          <ChartCard
            title=\"CPI vs growth ??? price dispersion\"
            subtitle=\"Bubble size = PPP stock share; China is the growth leader with near-zero CPI\"
          >
            <div className=\"h-96 w-full min-w-0\">
              <ResponsiveContainer width=\"100%\" height=\"100%\">
                <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#e2e8f0\" />
                  <XAxis
                    type=\"number\"
                    dataKey=\"x\"
                    name=\"CPI\"
                    unit=\"%\"
                    domain={[0, 5.5]}
                    tick={{ fontSize: 11 }}
                    label={{ value: \"CPI YoY %\", position: \"insideBottom\", offset: -2, fontSize: 11 }}
                  />
                  <YAxis
                    type=\"number\"
                    dataKey=\"y\"
                    name=\"GDP\"
                    unit=\"%\"
                    domain={[0, 8.5]}
                    tick={{ fontSize: 11 }}
                    label={{ value: \"GDP %\", angle: -90, position: \"insideLeft\", fontSize: 11 }}
                  />
                  <ZAxis type=\"number\" dataKey=\"z\" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: \"3 3\" }}
                    formatter={(v: number, name: string) => [
                      \\\`\\\${Number(v).toFixed(1)}%\\\`,
                      name === \"x\" ? \"CPI\" : name === \"y\" ? \"GDP\" : name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? \"\"
                    }
                  />
                  <Scatter data={priceScatter}>
                    {priceScatter.map((p) => (
                      <Cell key={p.id} fill={p.fill} />
