"
const fs = require('fs');
const content = String.raw\`\"use client\";

import { useMemo, useState } from \"react\";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from \"recharts\";
import { Tooltip } from \"@/components/charts/SortedTooltip\";
import {
  CPB_PATH,
  EXPORT_CONCENTRATION_CURVE,
  EXPORT_VALUE_SHARES,
  GROWTH_CONCENTRATION_CURVE,
  GROWTH_CONTRIB_Q2_SENS,
  GROWTH_CONTRIB_SHARES,
  GROWTH_Q2_CONCENTRATION_CURVE,
  HARD_DATA_METERS,
  HEADLINE,
  LENS_COMPARE,
  PPP_CONCENTRATION_CURVE,
  PPP_STOCK_SHARES,
  PRICE_LADDER,
  SCOREBOARD,
  SOURCE_NOTE,
  TRADE_CONCENTRATION_CURVE,
  TRADE_GROWTH_SHARES,
  VINTAGE_DELTAS,
  fmtPct,
  fmtPp,
  namedShares,
} from \"@/data/macro-growth-trade-concentration-2026q3-data\";

// viz-types: vintage delta bars, Lorenz area+line, growth base/Q2 bars, CPB rebound line, trade donut, hard-data dumbbells, price scatter, lens scatter | layout: default

type ViewId = \"scoreboard\" | \"growth\" | \"trade\" | \"prices\";
type GrowthVintage = \"base\" | \"q2\";
type CurveLens = \"ppp\" | \"growth\" | \"growth-q2\" | \"trade\" | \"exports\";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className=\"w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm\">
      <div className=\"border-b border-slate-100 bg-slate-50 px-5 py-4\">
        <h3 className=\"text-lg font-bold text-slate-900\">{title}</h3>
        {subtitle && <p className=\"mt-1 text-sm text-slate-500\">{subtitle}</p>}
      </div>
      <div className=\"p-4 sm:p-6\">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className=\"flex flex-wrap items-center gap-2\">
      <span className=\"text-xs font-semibold uppercase tracking-wide text-slate-500\">
        {label}
      </span>
      <div className=\"inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5\">
        {options.map((o) => (
          <button
            key={o.id}
            type=\"button\"
            onClick={() => onChange(o.id)}
            className={\\\`rounded-md px-3 py-1.5 text-sm font-medium transition-colors \\\${
              value === o.id
                ? \"bg-slate-900 text-white\"
                : \"text-slate-600 hover:bg-slate-50\"
            }\\\`}
          >
            {o.label}
          </button>
