                    label={{ value: \"GDP %\", angle: -90, position: \"insideLeft\", fontSize: 11 }}
                  />
                  <ZAxis type=\"number\" dataKey=\"z\" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: \"3 3\" }}
                    formatter={(v: number, name: string) => [
                      \\\`\\\${Number(v).toFixed(1)}%\\\`,
                      name === \"x\" ? \"CPI\" : name === \"y\" ? \"GDP\" : name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? \"\"
                    }
                  />
                  <Scatter data={priceScatter}>
                    {priceScatter.map((p) => (
                      <Cell key={p.id} fill={p.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title=\"Aug price meters\"
            subtitle=\"YoY cooling vs SAAR heat ??? geometry unchanged\"
          >
            <div className=\"space-y-4 text-sm text-slate-700\">
              <div className=\"grid grid-cols-2 gap-3\">
                <div className=\"rounded-lg border border-slate-200 bg-slate-50 px-4 py-3\">
                  <p className=\"text-xs uppercase text-slate-500\">US CPI Jul YoY</p>
                  <p className=\"text-2xl font-bold text-sky-700\">{fmtPct(HEADLINE.usCpiJulYoy, 1)}</p>
                </div>
                <div className=\"rounded-lg border border-slate-200 bg-slate-50 px-4 py-3\">
                  <p className=\"text-xs uppercase text-slate-500\">US PCE Jun YoY</p>
                  <p className=\"text-2xl font-bold text-violet-700\">{fmtPct(HEADLINE.usPceJunYoy, 1)}</p>
                </div>
                <div className=\"rounded-lg border border-slate-200 bg-slate-50 px-4 py-3\">
                  <p className=\"text-xs uppercase text-slate-500\">US PCE Q2 SAAR</p>
                  <p className=\"text-2xl font-bold text-rose-700\">{fmtPct(HEADLINE.usPceQ2Saar, 1)}</p>
                </div>
                <div className=\"rounded-lg border border-slate-200 bg-slate-50 px-4 py-3\">
                  <p className=\"text-xs uppercase text-slate-500\">EA HICP Jul</p>
                  <p className=\"text-2xl font-bold text-indigo-700\">{fmtPct(HEADLINE.eaHicpJulYoy, 1)}</p>
                </div>
              </div>
              <p className=\"leading-relaxed text-slate-600\">
                Elevated-CPI economies still account for roughly {fmtPct(HEADLINE.elevatedCpiGdpSharePct)} of
                world PPP GDP. China ({fmtPct(HEADLINE.chinaCpi2025, 1)} CPI) leads growth contribution while
                contributing almost nothing to the global price impulse ??? the soft-landing geometry the
                concentration lens is built to show.
              </p>
            </div>
          </ChartCard>
        </div>
      )}

      <p className=\"text-xs leading-relaxed text-slate-500\">{SOURCE_NOTE}</p>
    </div>
  );
}
\`;
