            subtitle={
              growthVintage === "q2"
                ? "Illustrative run-rate using China 4.3% YoY and US 1.5% SAAR"
                : "Carried 2025 weight ?? growth / world growth"
            }
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={growthBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 35]}
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={40}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number) => [
                      fmtPct(v, 1),
                      "Share of world growth",
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.label ?? ""}
                  />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {growthBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="PPP GDP stock ladder"
            subtitle="Carried ~2025 weights ??? China ?? US ?? India = 42% Top-3"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={pppBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 22]}
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={40}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number) => [
                      fmtPct(v, 1),
                      "PPP stock share",
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.label ?? ""}
                  />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {pppBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "trade" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Merchandise trade-growth contribution"
            subtitle="WTO 2025 regional decomposition ??? Asia 71% / 3.2 pp"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={tradePie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {tradePie.map((s) => (
                      <Cell key={s.name} fill={s.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v: number) => [
                      fmtPct(v, 0),
                      "Share of vol. growth",
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="CPB merchandise volume rebound"
            subtitle="Mar???May MoM path ??? flow overlay, not a re-rank of 2025 shares"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart
                  data={CPB_PATH}
                  margin={{ top: 12, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="month" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" domain={[-3, 2]} />
                  <Tooltip
                    formatter={(v: number) => [
                      `${Number(v).toFixed(1)}% MoM`,
                      "CPB",
                    ]}
                  />
                  <Line
                    type="monotone"
                    dataKey="mom"
                    stroke="#0ea5e9"
                    strokeWidth={3}
                    dot={{ r: 5, fill: "#0ea5e9" }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Goods export value shares"
            subtitle="China ?? US ?? Germany = 29% Top-3 of ~$26.3T merch exports"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={exportNamed}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip
                    formatter={(v: number) => [
                      fmtPct(v, 1),
                      "Export value share",
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.label ?? ""}
                  />
                  <Bar dataKey="sharePct" radius={[4, 4, 0, 0]}>
                    {exportNamed.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Scoreboard notes"
            subtitle="Confidence by perimeter"
          >
            <ul className="space-y-3 text-sm text-slate-600">
              {SCOREBOARD.map((s) => (
                <li
                  key={s.id}
                  className="flex gap-3 border-b border-slate-100 pb-2"
                >
                  <span
                    className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full"
                    style={{ background: s.color }}
                  />
                  <div>
                    <p className="font-semibold text-slate-800">
                      {s.label}: Top-1 {fmtPct(s.top1Pct)} ?? Top-3{" "}
                      {fmtPct(s.top3Pct)}
                    </p>
                    <p className="text-xs text-slate-500">
                      {s.confidence} ??? {s.note}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      {view === "prices" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="CPI vs growth ??? price dispersion"
            subtitle="Bubble size = PPP stock share; China leads growth with near-zero CPI"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
